using NUnit.Framework;
using UnityEngine;
using RiftRally.Core;
using RiftRally.Net;

namespace RiftRally.Tests
{
    /// <summary>
    /// The wire format, checked against the exact JSON the Node server sends.
    ///
    /// The payloads below are copied from the server's own messages rather than generated by
    /// the client, because the failure this guards against is silent: JsonUtility does not
    /// error on a field it cannot match, it leaves the default value. A renamed field on
    /// either side would show up in a headset as a stone at the origin or a score of zero,
    /// with nothing in the log.
    /// </summary>
    public class NetProtocolTests
    {
        [Test]
        public void StartingTheClientDeletesTokensLeftByOlderBuilds()
        {
            PlayerPrefs.SetString("riftrally.token", "legacy-bearer");
            PlayerPrefs.Save();

            var go = new GameObject("RiftNetClient_SecurityTest");
            go.AddComponent<RiftNetClient>();

            Assert.IsFalse(PlayerPrefs.HasKey("riftrally.token"),
                "an in-place upgrade must remove the old long-lived credential");
            Object.DestroyImmediate(go);
        }

        [Test]
        public void TheEnvelopeTypeIsReadableBeforeThePayloadIsKnown()
        {
            var envelope = RiftNetClient.Parse<NetEnvelope>("{\"type\":\"roundScored\",\"junk\":1}");
            Assert.AreEqual("roundScored", envelope.type,
                "the type tag must be readable without knowing the rest of the shape");
        }

        [Test]
        public void AMalformedMessageIsIgnoredRatherThanThrowing()
        {
            Assert.IsNull(RiftNetClient.Parse<NetEnvelope>("{ not json"));
            Assert.IsNull(RiftNetClient.Parse<NetEnvelope>(null));
            Assert.IsNull(RiftNetClient.Parse<NetEnvelope>(string.Empty));
        }

        [Test]
        public void ARoomSnapshotParsesEveryFieldTheGameNeeds()
        {
            const string json = @"{
              ""type"":""matchStart"",
              ""room"":{
                ""code"":""KTKK"",""state"":""playing"",""seed"":820613484,""round"":1,
                ""roundsWon"":[0,0],""totalPoints"":[0,0],""hammer"":1,""turnSeat"":0,
                ""stonesThrown"":0,""stoneNumber"":1,""modifier"":null,""winnerSeat"":null,
                ""endedReason"":null,""isPublic"":false,
                ""players"":[
                  {""id"":""a"",""displayName"":""Winner"",""kind"":""guest"",""rating"":1000,
                   ""ready"":true,""connected"":true},
                  {""id"":""b"",""displayName"":""Loser"",""kind"":""account"",""rating"":980,
                   ""ready"":true,""connected"":true}]
              }}";

            var message = RiftNetClient.Parse<NetRoomMessage>(json);

            Assert.IsNotNull(message?.room);
            Assert.AreEqual("KTKK", message.room.code);
            Assert.IsTrue(message.room.IsPlaying);
            Assert.AreEqual(1, message.room.round);
            Assert.AreEqual(1, message.room.hammer);
            Assert.AreEqual(0, message.room.turnSeat);
            Assert.AreEqual(2, message.room.players.Length);
            Assert.AreEqual("Winner", message.room.players[0].displayName);
            Assert.AreEqual("account", message.room.players[1].kind);
            Assert.AreEqual(820613484, message.room.seed);
        }

        [Test]
        public void AJsonNullDecodesToZeroWhichIsWhyTheServerSendsMinusOne()
        {
            // The trap this whole convention exists for: JsonUtility does not leave an int
            // field at its default when the JSON holds null - it writes 0. Since 0 is a real
            // modifier index, a null would quietly switch the cross current on during round
            // one. The server therefore sends -1 for "no modifier", and this test pins the
            // decoder behaviour so nobody "simplifies" it back to null.
            var withNull = RiftNetClient.Parse<NetRoomMessage>(
                "{\"room\":{\"code\":\"AAAA\",\"state\":\"playing\",\"round\":1,\"modifier\":null}}");

            Assert.IsNotNull(withNull?.room);
            Assert.AreEqual(0, withNull.room.modifier,
                "null decodes to 0, which is indistinguishable from the first modifier");

            // The real wire format, which is unambiguous.
            var withSentinel = RiftNetClient.Parse<NetRoomMessage>(
                "{\"room\":{\"code\":\"AAAA\",\"state\":\"playing\",\"round\":1,\"modifier\":-1}}");

            Assert.That(withSentinel.room.modifier, Is.LessThan(0), "a clean rink");

            var withModifier = RiftNetClient.Parse<NetRoomMessage>(
                "{\"room\":{\"code\":\"AAAA\",\"state\":\"playing\",\"round\":2,\"modifier\":2}}");

            Assert.AreEqual(2, withModifier.room.modifier);
        }

        [Test]
        public void AnAbsentModifierFieldLeavesTheRinkClean()
        {
            // An older or partial message must not activate anything.
            var message = RiftNetClient.Parse<NetRoomMessage>(
                "{\"room\":{\"code\":\"AAAA\",\"state\":\"playing\",\"round\":2}}");

            Assert.That(message.room.modifier, Is.LessThan(0));
        }

        [Test]
        public void AnOpponentThrowCarriesTheLaunchAndTheRestingStones()
        {
            const string json = @"{
              ""type"":""opponentThrow"",""seat"":1,
              ""launch"":{""x"":0.1,""z"":-0.6,""dirX"":0.05,""dirZ"":1,""speed"":1.4,""spin"":2},
              ""stones"":[{""id"":""s0"",""seat"":0,""x"":0.02,""z"":0.46},
                          {""id"":""s1"",""seat"":1,""x"":-0.05,""z"":0.4}]}";

            var message = RiftNetClient.Parse<NetOpponentThrow>(json);

            Assert.AreEqual(1, message.seat);
            Assert.AreEqual(1.4f, message.launch.speed, 1e-4f);
            Assert.AreEqual(1f, message.launch.dirZ, 1e-4f);
            Assert.AreEqual(2, message.stones.Length);
            Assert.AreEqual(0.46f, message.stones[0].z, 1e-4f);
            Assert.AreEqual(1, message.stones[1].seat);
        }

        [Test]
        public void ARoundResultParsesIncludingABlankRound()
        {
            var scored = RiftNetClient.Parse<NetRoundScored>(
                @"{""result"":{""blank"":false,""winnerSeat"":0,""points"":2,
                   ""closestDistance"":0.021,""inHouse"":3},
                   ""room"":{""roundsWon"":[1,0],""totalPoints"":[2,0],""state"":""playing""}}");

            Assert.IsFalse(scored.result.blank);
            Assert.AreEqual(0, scored.result.winnerSeat);
            Assert.AreEqual(2, scored.result.points);
            Assert.AreEqual(1, scored.room.roundsWon[0]);

            // A blank round is identified by its flag, never by its seat: the seat is only
            // meaningful when blank is false, which is why the HUD reads the flag first.
            var blank = RiftNetClient.Parse<NetRoundScored>(
                @"{""result"":{""blank"":true,""winnerSeat"":-1,""points"":0}}");

            Assert.IsTrue(blank.result.blank);
            Assert.That(blank.result.winnerSeat, Is.LessThan(0),
                "the server sends -1 rather than null for an absent winner");
        }

        [Test]
        public void MatchOverCarriesTheUpdatedPlayerRecord()
        {
            const string json = @"{
              ""type"":""matchOver"",""youWon"":true,""winnerSeat"":0,""reason"":""completed"",
              ""player"":{""id"":""a"",""kind"":""guest"",""displayName"":""Winner"",
                          ""rating"":1014,""wins"":1,""losses"":0,""matches"":1,
                          ""pointsFor"":4,""pointsAgainst"":1,""bestRound"":3},
              ""rank"":1}";

            var message = RiftNetClient.Parse<NetMatchOver>(json);

            Assert.IsTrue(message.youWon);
            Assert.AreEqual(1014, message.player.rating);
            Assert.AreEqual(1, message.rank);
            Assert.IsTrue(message.player.IsGuest);
        }

        [Test]
        public void TheLeaderboardParsesGuestsAndAccountsTogether()
        {
            const string json = @"{
              ""entries"":[
                {""rank"":1,""id"":""a"",""kind"":""account"",""displayName"":""Accounty"",
                 ""rating"":1030,""wins"":2,""losses"":0,""matches"":2},
                {""rank"":2,""id"":""b"",""kind"":""guest"",""displayName"":""Guesty"",
                 ""rating"":970,""wins"":0,""losses"":2,""matches"":2}],
              ""me"":{""rank"":2,""id"":""b"",""kind"":""guest"",""displayName"":""Guesty"",
                      ""rating"":970,""wins"":0,""losses"":2,""matches"":2}}";

            var board = RiftNetClient.Parse<NetLeaderboard>(json);

            Assert.AreEqual(2, board.entries.Length);
            Assert.IsFalse(board.entries[0].IsGuest);
            Assert.IsTrue(board.entries[1].IsGuest, "guests are ranked on the same board");
            Assert.AreEqual(2, board.me.rank);
        }

        [Test]
        public void AnErrorMessageParses()
        {
            var error = RiftNetClient.Parse<NetError>(
                "{\"type\":\"error\",\"code\":\"NOT_YOUR_TURN\",\"message\":\"it is not your turn\"}");

            Assert.AreEqual("NOT_YOUR_TURN", error.code);
            Assert.AreEqual("it is not your turn", error.message);
        }

        [Test]
        public void OutboundRequestsSerialiseWithTheTypeTheServerExpects()
        {
            string join = JsonUtility.ToJson(new NetJoinRoomRequest { code = "KTKK" });
            StringAssert.Contains("\"type\":\"joinRoom\"", join);
            StringAssert.Contains("\"code\":\"KTKK\"", join);

            string ready = JsonUtility.ToJson(new NetReadyRequest());
            StringAssert.Contains("\"type\":\"ready\"", ready);

            string thrown = JsonUtility.ToJson(new NetThrowRequest
            {
                launch = new NetLaunch { speed = 1.2f, dirZ = 1f },
                stones = new[] { new NetStone { id = "s0", seat = 0, x = 0.01f, z = 0.46f } }
            });
            StringAssert.Contains("\"type\":\"throw\"", thrown);
            StringAssert.Contains("\"speed\":1.2", thrown);
            StringAssert.Contains("\"seat\":0", thrown);
        }

        [Test]
        public void SeatsMapToSidesConsistentlyInBothDirections()
        {
            // Seat 0 is always blue and seat 1 always orange. If this ever flipped, two
            // players would see each other's stones in the wrong colour and the scoreboard
            // would credit the wrong side.
            Assert.AreEqual(PlayerSide.One, NetMatchDriver.SeatToSide(0));
            Assert.AreEqual(PlayerSide.Two, NetMatchDriver.SeatToSide(1));
            Assert.AreEqual(0, NetMatchDriver.SideToSeat(PlayerSide.One));
            Assert.AreEqual(1, NetMatchDriver.SideToSeat(PlayerSide.Two));

            Assert.AreEqual(PlayerSide.One, NetMatchDriver.SeatToSide(
                NetMatchDriver.SideToSeat(PlayerSide.One)));
            Assert.AreEqual(PlayerSide.Two, NetMatchDriver.SeatToSide(
                NetMatchDriver.SideToSeat(PlayerSide.Two)));
        }

        [Test]
        public void AnUnexpectedSeatFallsBackToBlueRatherThanThrowing()
        {
            Assert.AreEqual(PlayerSide.One, NetMatchDriver.SeatToSide(-1));
            Assert.AreEqual(PlayerSide.One, NetMatchDriver.SeatToSide(7));
        }
    }
}
